import{_ as e,c as n,o,ag as a}from"./chunks/framework.Bzez9NG9.js";const r="/space/img/new_content_select.png",s="/space/img/2new_content.png",i="/space/img/configure_select.png",c="/space/img/12update_select.png",_=JSON.parse('{"title":"Content","description":"Manage cached model documentation and TM1 logs, including content creation, refreshes, retention, and exports.","frontmatter":{"title":"Content","description":"Manage cached model documentation and TM1 logs, including content creation, refreshes, retention, and exports.","keywords":["synchronization","stale data","datasets"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/content.md","filePath":"doc/configuration/content.md"}'),d={name:"doc/configuration/content.md"};function l(g,t,p,h,u,m){return o(),n("div",null,t[0]||(t[0]=[a('<h1 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h1><p>The <strong>Content</strong> tab tracks all cached datasets SPACE stores (documentation exports, audit logs, server logs, transaction logs).</p><p><img src="'+r+'" alt="Content list" data-zoomable=""></p><p>Each row shows the source <strong>Connection</strong>, <strong>Content</strong> type, and who last <strong>Updated</strong> it. Use the toolbar to configure settings, run an update, export data, delete stale content, or cancel selection mode.</p><h2 id="creating-content" tabindex="-1">Creating content <a class="header-anchor" href="#creating-content" aria-label="Permalink to &quot;Creating content&quot;">​</a></h2><p>Click <strong>Create</strong> to register a new content item.</p><p><img src="'+s+'" alt="New content modal" data-zoomable=""></p><p>Choose the TM1 connection and content type (Documentation, Audit log, Server log, Transaction log). The new item appears in the table where you can configure retention and run updates.</p><h2 id="configuring-content" tabindex="-1">Configuring content <a class="header-anchor" href="#configuring-content" aria-label="Permalink to &quot;Configuring content&quot;">​</a></h2><p>Select a row and choose <strong>Configure</strong> to view metadata and adjust settings.</p><p><img src="'+i+'" alt="Content settings modal" data-zoomable=""></p><p>The modal displays:</p><ul><li><strong>Updated at / Updated by</strong> – last sync details.</li><li><strong>Update now</strong> – trigger an immediate refresh without waiting for the scheduled job.</li><li><strong>Retain months</strong> (for log content) – how long data stays available in SPACE.</li></ul><h2 id="updating-content-manually" tabindex="-1">Updating content manually <a class="header-anchor" href="#updating-content-manually" aria-label="Permalink to &quot;Updating content manually&quot;">​</a></h2><p>If you need to refresh before the next scheduled job, select a row and click <strong>Update</strong>.</p><p><img src="'+c+'" alt="Manual update confirmation" data-zoomable=""></p><p>Confirm the prompt to run the update immediately. Use <strong>Export</strong> from the toolbar to download the current dataset for offline analysis.</p><h2 id="scheduled-updates-and-viewing-content" tabindex="-1">Scheduled updates and viewing content <a class="header-anchor" href="#scheduled-updates-and-viewing-content" aria-label="Permalink to &quot;Scheduled updates and viewing content&quot;">​</a></h2><p>Use <a href="./jobs.html">Jobs</a> to schedule regular updates. Open <a href="./../planning-analytics/model-documentation.html">Model documentation</a> to explore the diagram or <a href="./../planning-analytics/logs.html">Logs</a> to search the synchronized logs.</p>',19)]))}const b=e(d,[["render",l]]);export{_ as __pageData,b as default};
